import React, { useState, useEffect, useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import {
  Sidebar,
  useResponsive,
  BREAKPOINTS,
} from '@linm-soft-org/linm-web-common-components';
import {
  getSidebarCollapsed,
  setSidebarCollapsed,
} from '../utils/sidebarCollapsedStorage';
import { buildMedicalIncidentSections } from '../utils/navUtils';
import { scykRoutes } from '../config/scykRoutes';
import { runWithLeaveGuard } from '@linm-soft-org/linm-web-common-components';
import { useAppSelector } from '../store/hooks';
import { UserRole } from '../models/User';
import { STANDALONE_MOCK_USER, seedStandaloneAuth } from './mockAuth';

export const StandaloneMockNav: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { isMobile, isSmallDesktop } = useResponsive();
  const user = useAppSelector((s) => s.auth.user) ?? STANDALONE_MOCK_USER;

  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(() => {
    if (typeof window === 'undefined') return false;
    const w = window.innerWidth;
    if (w < BREAKPOINTS.mobile) return false;
    if (w < BREAKPOINTS.tablet) return true;
    return getSidebarCollapsed();
  });

  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false);

  // Chỉ theo breakpoint — cấm phụ thuộc isSidebarCollapsed (tránh setState loop → lag std).
  useEffect(() => {
    if (isMobile) {
      setIsSidebarCollapsed(false);
      return;
    }
    if (isSmallDesktop) {
      setIsSidebarCollapsed(true);
      return;
    }
    setIsSidebarCollapsed(getSidebarCollapsed());
  }, [isMobile, isSmallDesktop]);

  useEffect(() => {
    const handler = () => setIsMobileSidebarOpen((prev) => !prev);
    window.addEventListener('linm:nav:toggle-mobile', handler);
    return () => window.removeEventListener('linm:nav:toggle-mobile', handler);
  }, []);

  useEffect(() => {
    document.documentElement.style.setProperty(
      '--sidebar-width',
      isMobile
        ? isMobileSidebarOpen
          ? '280px'
          : '0px'
        : isSidebarCollapsed
          ? '64px'
          : '280px',
    );
  }, [isMobile, isMobileSidebarOpen, isSidebarCollapsed]);

  const handleToggleSidebar = useCallback(() => {
    setIsSidebarCollapsed((prev) => {
      const next = !prev;
      if (!isMobile) setSidebarCollapsed(next);
      return next;
    });
  }, [isMobile]);

  const handleNavigate = useCallback(
    (path: string) => {
      runWithLeaveGuard(path, () => {
        navigate(path);
        if (isMobile) setIsMobileSidebarOpen(false);
      });
    },
    [isMobile, navigate],
  );

  const handleLogout = useCallback(() => {
    seedStandaloneAuth(true);
    navigate('/dev');
  }, [navigate]);

  const sections = buildMedicalIncidentSections(user.role as UserRole);
  const fullName = user.fullName || 'Dev Standalone';
  const parts = fullName.trim().split(' ');
  const userInitials =
    parts.length >= 2
      ? (parts[parts.length - 2].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase()
      : fullName.charAt(0).toUpperCase();

  const roleLabel =
    user.role === UserRole.Admin
      ? 'Quản trị viên'
      : user.role === UserRole.Manager
        ? 'Quản lý'
        : user.role === UserRole.Staff
          ? 'Nhân viên'
          : 'Người dùng';

  return (
    <Sidebar
      sections={sections}
      activePath={location.pathname}
      userName={fullName}
      userRole={roleLabel}
      userInitials={userInitials}
      onNavigate={handleNavigate}
      onLogout={handleLogout}
      isCollapsed={isSidebarCollapsed}
      onToggleCollapse={handleToggleSidebar}
      isMobile={isMobile}
      isSmallDesktop={isSmallDesktop}
      isOpen={isMobileSidebarOpen}
      logoLabel="Sự Cố Y Khoa"
      logoHomePath={scykRoutes.home}
    />
  );
};

export default StandaloneMockNav;
