import { navigateToUrl } from 'single-spa';
import { isScykShellPath } from '../config/scykRoutes';
import { isStandalone } from '../dev/isStandalone';

/** Same event as Linm.Web.Navigation `forceShellNavigate` — keeps MemoryRouter in sync. */
export const LINM_NAV_FORCE_PATH_EVENT = 'linm:nav:force-path';

export type InAppNavigateFn = (to: string, options?: { replace?: boolean }) => void;

function stripTrailingSlash(path: string): string {
  if (path.length > 1 && path.endsWith('/')) return path.slice(0, -1);
  return path || '/';
}

/**
 * Shell: `navigateToUrl` (URL bar) + MemoryRouter `navigate` (route render).
 * `navigateToUrl` alone can leave MemoryRouter on a sub-route (e.g. detail)
 * while the shell URL already shows the list — back/sidebar appear broken.
 * Standalone: MemoryRouter navigate only.
 */
export function navigateInAppPath(
  path: string,
  navigate: InAppNavigateFn,
  options?: { replace?: boolean },
): void {
  const normalized = path.startsWith('/') ? path : `/${path}`;
  if (isStandalone) {
    navigate(normalized, { replace: options?.replace });
    return;
  }

  const target = stripTrailingSlash(normalized);
  const windowPath = stripTrailingSlash(window.location.pathname);

  navigateToUrl(normalized);

  // Only sync MemoryRouter for routes owned by this MFE — cross-app paths (/dashboard, …)
  // are handled by single-spa + MemoryRouterSync window listener.
  if (isScykShellPath(normalized)) {
    navigate(normalized, { replace: options?.replace ?? true });

    // Backup when collapsing sub-route → list (parity NavRoot `forceShellNavigate`).
    if (windowPath.startsWith(`${target}/`)) {
      window.setTimeout(() => {
        window.dispatchEvent(
          new CustomEvent(LINM_NAV_FORCE_PATH_EVENT, { detail: { path: target } }),
        );
      }, 0);
    }
  }
}
