import { AuthHydrate } from './bootstrap/AuthHydrate';
import { TenantBootstrapGate } from './bootstrap/tenantBootstrap';
import React, { Suspense } from 'react';
import { MemoryRouter, Routes, Route, Navigate, useParams } from 'react-router-dom';
import { Provider } from 'react-redux';
import { store } from './store/store';

import { ProtectedRoute } from './components/auth/ProtectedRoute';
import { AppLayout } from './components/layout/AppLayout';
import { SimpleNotFoundPage } from './components/layout/SimpleNotFoundPage';
import { isStandalone, showDevNav } from './dev/isStandalone';
import { StandaloneMockNav } from './standalone/StandaloneMockNav';
import { MemoryRouterSync } from './routing/MemoryRouterSync';
import { scykRoutes } from './config/scykRoutes';
import { ToastProvider, AlertProvider } from '@linm-soft-org/linm-web-common-components';

const MedicalIncidentsListPage = React.lazy(() => import('./pages/MedicalIncidentsListPage'));
const MedicalIncidentFormPage = React.lazy(() => import('./pages/MedicalIncidentFormPage'));
const MedicalIncidentReportPage = React.lazy(() => import('./pages/MedicalIncidentReportPage'));
const ServiceMismatchReportPage = React.lazy(() => import('./pages/ServiceMismatchReportPage'));
const FallIncidentReportPage = React.lazy(() => import('./pages/FallIncidentReportPage'));
const DailyIncidentReportsListPage = React.lazy(() => import('./pages/DailyIncidentReportsListPage'));
const DailyIncidentReportFormPage = React.lazy(() => import('./pages/DailyIncidentReportFormPage'));
const FallLocationWarningListPage = React.lazy(() => import('./pages/FallLocationWarningListPage'));
const FallLocationWarningFormPage = React.lazy(() => import('./pages/FallLocationWarningFormPage'));
const MonthlyReportListPage = React.lazy(() => import('./pages/MonthlyReportListPage'));
const MonthlyReportFormPage = React.lazy(() => import('./pages/MonthlyReportFormPage'));
const DevPage = React.lazy(() => import('./dev/DevPage'));

const PageSuspense = ({ children }: { children: React.ReactNode }) => (
  <Suspense fallback={<div style={{ padding: '2rem' }}>Đang tải...</div>}>
    {children}
  </Suspense>
);

const AppShell = () => (
  <>
    {isStandalone && <StandaloneMockNav />}
    <AppLayout />
  </>
);

const layoutElement = isStandalone ? (
  <AppShell />
) : (
  <ProtectedRoute>
    <AppLayout />
  </ProtectedRoute>
);

const initialPath = window.location.pathname + window.location.search || '/';

const LegacyMonthlyReportRedirect = () => {
  const { id } = useParams();
  return <Navigate to={id ? scykRoutes.monthlyReports.detail(id) : scykRoutes.monthlyReports.list} replace />;
};

const LegacyIncidentDetailRedirect = () => {
  const { id } = useParams();
  return <Navigate to={id ? scykRoutes.incidents.detail(id) : scykRoutes.incidents.list} replace />;
};

const LegacyFallWarningDetailRedirect = () => {
  const { id } = useParams();
  return <Navigate to={id ? scykRoutes.fallWarnings.detail(id) : scykRoutes.fallWarnings.list} replace />;
};

const legacyRedirects = (
  <>
    <Route path="medical-incidents" element={<Navigate to={scykRoutes.incidents.list} replace />} />
    <Route path="medical-incidents/new" element={<Navigate to={scykRoutes.incidents.new} replace />} />
    <Route path="medical-incidents/reports" element={<Navigate to={scykRoutes.reports.summary} replace />} />
    <Route path="medical-incidents/reports/service-mismatch" element={<Navigate to={scykRoutes.reports.serviceMismatch} replace />} />
    <Route path="medical-incidents/reports/fall" element={<Navigate to={scykRoutes.reports.fall} replace />} />
    <Route path="medical-incidents/daily-reports" element={<Navigate to={scykRoutes.dailyReports.list} replace />} />
    <Route path="medical-incidents/daily-reports/new" element={<Navigate to={scykRoutes.dailyReports.new} replace />} />
    <Route path="medical-incidents/monthly-reports" element={<Navigate to={scykRoutes.monthlyReports.list} replace />} />
    <Route path="medical-incidents/monthly-reports/new" element={<Navigate to={scykRoutes.monthlyReports.new} replace />} />
    <Route path="medical-incidents/monthly-reports/:id" element={<LegacyMonthlyReportRedirect />} />
    <Route path="medical-incidents/:id" element={<LegacyIncidentDetailRedirect />} />
    <Route path="fall-location-warnings" element={<Navigate to={scykRoutes.fallWarnings.list} replace />} />
    <Route path="fall-location-warnings/new" element={<Navigate to={scykRoutes.fallWarnings.new} replace />} />
    <Route path="fall-location-warnings/:id" element={<LegacyFallWarningDetailRedirect />} />
  </>
);

const lazyPage = (el: React.ReactNode) => <PageSuspense>{el}</PageSuspense>;

const Root: React.FC = () => (
  <Provider store={store}>
    <TenantBootstrapGate>
      <AuthHydrate>
        <AlertProvider>
          <ToastProvider>
            <MemoryRouter
              initialEntries={[initialPath]}
              initialIndex={0}
              future={{ v7_startTransition: true, v7_relativeSplatPath: true }}
            >
              <MemoryRouterSync />
              <Routes>
                <Route path="/" element={layoutElement}>
                  {showDevNav && (
                    <>
                      <Route index element={<Navigate to="/dev" replace />} />
                      <Route path="dev" element={lazyPage(<DevPage />)} />
                    </>
                  )}
                  {legacyRedirects}
                  <Route path="scyk/su-co" element={lazyPage(<MedicalIncidentsListPage />)} />
                  <Route path="scyk/su-co/new" element={lazyPage(<MedicalIncidentFormPage />)} />
                  <Route path="scyk/su-co/:id" element={lazyPage(<MedicalIncidentFormPage />)} />
                  <Route path="scyk/bc/thong-ke" element={lazyPage(<MedicalIncidentReportPage />)} />
                  <Route path="scyk/bc/nham-dv" element={lazyPage(<ServiceMismatchReportPage />)} />
                  <Route path="scyk/bc/te-nga" element={lazyPage(<FallIncidentReportPage />)} />
                  <Route path="scyk/bc/hang-ngay" element={lazyPage(<DailyIncidentReportsListPage />)} />
                  <Route path="scyk/bc/hang-ngay/new" element={lazyPage(<DailyIncidentReportFormPage />)} />
                  <Route path="scyk/bc/tong-hop-thang" element={lazyPage(<MonthlyReportListPage />)} />
                  <Route path="scyk/bc/tong-hop-thang/new" element={lazyPage(<MonthlyReportFormPage />)} />
                  <Route path="scyk/bc/tong-hop-thang/:id" element={lazyPage(<MonthlyReportFormPage />)} />
                  <Route path="scyk/canh-bao/te-nga" element={lazyPage(<FallLocationWarningListPage />)} />
                  <Route path="scyk/canh-bao/te-nga/new" element={lazyPage(<FallLocationWarningFormPage />)} />
                  <Route path="scyk/canh-bao/te-nga/:id" element={lazyPage(<FallLocationWarningFormPage />)} />
                  <Route path="*" element={<SimpleNotFoundPage />} />
                </Route>
              </Routes>
            </MemoryRouter>
          </ToastProvider>
        </AlertProvider>
      </AuthHydrate>
    </TenantBootstrapGate>
  </Provider>
);

export default Root;
