/* Package SSOT — cấm clone (GAP-FILTER-BAR-05). Filter-layout không có export \`style\` → path file. */

/* TableCard không listShell: .cardHeader flex row — package \`flex: 0 0 auto\`
   co header theo title. Child phải full width (cấm clone file package). */
[data-lin-list-layout='erp-filter-bar'] [class*='cardHeader']:not([class*='cardHeaderList']) > * {
  width: 100% !important;
  max-width: 100% !important;
  min-width: 0 !important;
  flex: 1 1 auto !important;
}

/* Package ép leading > * = 180px và mọi input width 100% → checkbox + nhãn tách xa.
   Clear / includeDraft: width auto · checkbox không stretch. */
[data-lin-list-layout='erp-filter-bar']
  [data-lin-erp-list-filter-leading]
  > [data-testid\$='-field-includeDraft'],
[data-lin-list-layout='erp-filter-bar']
  [data-lin-erp-list-filter-leading]
  > [data-testid\$='-field-clear'] {
  width: auto !important;
  min-width: 0 !important;
  max-width: none !important;
  display: flex !important;
  flex-direction: column !important;
  justify-content: flex-end !important;
}

[data-lin-list-layout='erp-filter-bar']
  [data-lin-erp-list-filter-leading]
  input[type='checkbox'] {
  width: 15px !important;
  min-width: 15px !important;
  max-width: 15px !important;
}

body {
  background-color: var(--ds-color-bg-subtle, #F6F6F6);
}

/* ========================================
   Form Input Consistency (ERP Standard)
   All inputs, selects, and comboboxes must
   share the same visual rhythm.
   Rule: web-app/rule/form-field-select-css.md
   ======================================== */

select,
input[type="text"],
input[type="search"],
input[type="number"],
input[type="date"],
input[type="datetime-local"],
textarea {
  padding: 6px 10px;
  border: 1px solid var(--ds-color-border, #BABCBE);
  border-radius: var(--ds-radius-md, 4px);
  font-size: var(--ds-font-size-input-desktop, 13px);
  color: var(--ds-color-text-heading, #1A1A1A);
  background: var(--ds-color-bg-white, #FFFFFF);
  transition: border-color 0.15s, box-shadow 0.15s;
  line-height: 1.4;
  min-height: 32px;
}

select:focus,
input[type="text"]:focus,
input[type="search"]:focus,
input[type="number"]:focus,
input[type="date"]:focus,
input[type="datetime-local"]:focus,
textarea:focus {
  outline: none;
  border-color: var(--ds-color-primary, #2563eb);
  box-shadow: var(--ds-focus-shadow, 0px 0px 4px #BABCBE);
}

select:disabled,
input:disabled,
textarea:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  background: var(--ds-color-bg-subtle, #F6F6F6);
}

/* Combobox dropdown options consistency */
select option {
  padding: 6px 10px;
  font-size: var(--ds-font-size-input-desktop, 13px);
  color: var(--ds-color-text-heading, #1A1A1A);
  background: var(--ds-color-bg-white, #FFFFFF);
}

/* Select placeholder — first option as placeholder pattern */
select option[value=""] {
  color: var(--ds-color-text-tertiary, #6D6D6D);
}

/* Utility Classes */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.flex {
  display: flex;
}

.flex-col {
  flex-direction: column;
}

.items-center {
  align-items: center;
}

.justify-between {
  justify-content: space-between;
}

.gap-sm {
  gap: 8px;
}

.gap-md {
  gap: 16px;
}

.gap-lg {
  gap: 24px;
}

.mt-sm {
  margin-top: 8px;
}

.mt-md {
  margin-top: 16px;
}

.mt-lg {
  margin-top: 24px;
}

.mb-sm {
  margin-bottom: 8px;
}

.mb-md {
  margin-bottom: 16px;
}

.mb-lg {
  margin-bottom: 24px;
}

.p-sm {
  padding: 8px;
}

.p-md {
  padding: 16px;
}

.p-lg {
  padding: 24px;
}

.rounded-sm {
  border-radius: 4px;
}

.rounded-md {
  border-radius: 8px;
}

.rounded-lg {
  border-radius: 8px;
}

.shadow {
  box-shadow: var(--ds-shadow, 0 1px 3px 0 rgba(0, 0, 0, 0.1));
}

.shadow-md {
  box-shadow: var(--ds-shadow-md, 0 4px 6px -1px rgba(0, 0, 0, 0.1));
}

.shadow-lg {
  box-shadow: var(--ds-shadow-lg, 0 10px 15px -3px rgba(0, 0, 0, 0.1));
}

/* Responsive & Overflow Prevention */
* {
  max-width: 100%;
}

img,
video,
iframe {
  max-width: 100%;
  height: auto;
}

/* Mobile Responsive Utilities */
@media (max-width: 768px) {
  .container {
    padding: 0 16px;
  }

  /* Prevent horizontal overflow on mobile */
  body,
  #root,
  .layout {
    max-width: 100vw;
    overflow-x: hidden;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 8px;
  }

  /* Stack buttons on very small screens */
  button + button {
    margin-left: 0;
    margin-top: var(--spacing-xs, 0.25rem);
  }
}
