import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';
import type { DailyIncidentReport, DailyIncidentReportFilters, DailyIncidentReportStats } from '../../models/DailyIncidentReport';

export interface DailyReportPagedResult {
  items:      DailyIncidentReport[];
  total:      number;
  page:       number;
  pageSize:   number;
  totalPages: number;
}

const BASE = '/daily-incident-reports';

export const dailyIncidentReportEndpoint = {
  getList: async (
    filters: DailyIncidentReportFilters,
    page     = 1,
    pageSize = 20,
  ): Promise<DailyReportPagedResult> => {
    const qs = new URLSearchParams();
    if (filters.search)                  qs.set('search',       filters.search);
    if (filters.fromDate)                qs.set('fromDate',     filters.fromDate);
    if (filters.toDate)                  qs.set('toDate',       filters.toDate);
    if (filters.departmentId)            qs.set('departmentId', filters.departmentId);
    if (filters.hasIncident !== undefined) qs.set('hasIncident', String(filters.hasIncident));
    qs.set('page',     String(page));
    qs.set('pageSize', String(pageSize));

    const res = await apiClient.get<BffResponse<DailyReportPagedResult>>(`${BASE}?${qs}`);
    return unwrap(res);
  },

  create: async (data: Omit<DailyIncidentReport, 'id' | 'idCode' | 'createdById' | 'createdByName' | 'createdAt' | 'updatedAt'>): Promise<DailyIncidentReport> => {
    const res = await apiClient.post<BffResponse<DailyIncidentReport>>(BASE, data);
    return unwrap(res);
  },

  getStats: async (filters: DailyIncidentReportFilters): Promise<DailyIncidentReportStats> => {
    const qs = new URLSearchParams();
    if (filters.fromDate)     qs.set('fromDate',     filters.fromDate);
    if (filters.toDate)       qs.set('toDate',       filters.toDate);
    if (filters.departmentId) qs.set('departmentId', filters.departmentId);
    const res = await apiClient.get<BffResponse<DailyIncidentReportStats>>(`${BASE}/stats?${qs}`);
    return unwrap(res);
  },

  exportAll: async (filters: DailyIncidentReportFilters): Promise<Blob> => {
    const body: Record<string, unknown> = {};
    if (filters.fromDate)              body['fromDate']     = filters.fromDate;
    if (filters.toDate)                body['toDate']       = filters.toDate;
    if (filters.departmentId)          body['departmentId'] = filters.departmentId;
    if (filters.hasIncident != null)   body['hasIncident']  = filters.hasIncident;
    return apiClient.postBlob(`${BASE}/export`, body);
  },
};
